import datetime
import re
from bisect import bisect_left
from calendar import monthrange
from functools import lru_cache


_ITEM = re.compile(r"(?:(\*)|([0-9]+)(?:-([0-9]+))?)(?:/([0-9]+))?")


def _capped_uint(text: str, cap: int) -> int:
    """Parse unsigned digits, returning cap + 1 for numbers above cap."""
    # Avoid Python's integer-string length limit, including for leading zeros.
    text = text.lstrip("0") or "0"
    if len(text) > len(str(cap)):
        return cap + 1
    return min(int(text), cap + 1)


def _parse_field(text: str, low: int, high: int) -> tuple:
    values = set()

    for item in text.split(","):
        match = _ITEM.fullmatch(item)
        if match is None:
            raise ValueError(f"Invalid cron item: {item!r}")

        star, first_text, last_text, step_text = match.groups()

        if star is not None:
            first, last = low, high
        else:
            first = _capped_uint(first_text, high)
            last = (
                first
                if last_text is None
                else _capped_uint(last_text, high)
            )
            if not (low <= first <= high and low <= last <= high):
                raise ValueError(f"Cron value outside {low}-{high}: {item!r}")
            if first > last:
                raise ValueError(f"Reversed cron range: {item!r}")
            if step_text is not None and last_text is None:
                raise ValueError(f"A step requires '*' or a range: {item!r}")

        step = 1
        if step_text is not None:
            # Any step larger than the field's width selects only `first`.
            step = _capped_uint(step_text, high - low + 1)
            if step == 0:
                raise ValueError(f"Cron step must be positive: {item!r}")

        values.update(range(first, last + 1, step))

    return tuple(sorted(values))


@lru_cache(maxsize=4096)
def _compile(fields: tuple) -> tuple:
    if len(fields) != 5:
        raise ValueError("A cron expression must have exactly five fields")

    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    dom = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    raw_dow = _parse_field(fields[4], 0, 7)

    # Normalize Sunday only after expanding ranges and steps.
    dow = tuple(sorted({value % 7 for value in raw_dow}))
    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"

    # With restricted DOW, every selected month has a matching weekday.
    # Otherwise DOM decides: use a leap year for maximum month lengths.
    if dow_star:
        maximum_length = max(monthrange(2000, month)[1] for month in months)
        if dom[0] > maximum_length:
            raise ValueError("Cron expression can never fire")

    return minutes, hours, dom, months, dow, dom_star, dow_star


def _matching_days(
    year: int,
    month: int,
    dom: tuple,
    dow: tuple,
    dom_star: bool,
    dow_star: bool,
):
    first_weekday, length = monthrange(year, month)

    if dom_star and dow_star:
        return range(1, length + 1)

    if dow_star:
        return tuple(day for day in dom if day <= length)

    # calendar uses Monday=0; cron uses Sunday=0.
    first_cron_weekday = (first_weekday + 1) % 7
    days = set()
    for weekday in dow:
        first_day = 1 + (weekday - first_cron_weekday) % 7
        days.update(range(first_day, length + 1, 7))

    if not dom_star:
        # Both fields restricted: DOM OR DOW.
        days.update(day for day in dom if day <= length)

    return sorted(days)


def _time_at_or_after(
    hours: tuple, minutes: tuple, hour: int, minute: int
):
    hour_index = bisect_left(hours, hour)
    if hour_index == len(hours):
        return None

    if hours[hour_index] == hour:
        minute_index = bisect_left(minutes, minute)
        if minute_index < len(minutes):
            return hour, minutes[minute_index]
        hour_index += 1

    if hour_index == len(hours):
        return None

    return hours[hour_index], minutes[0]


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Return the earliest cron fire time strictly later than naive `after`.

    Searches selected months and calendar days, never individual minutes.
    Compiled expressions are cached for repeated dashboard calculations.
    """
    if after.utcoffset() is not None:
        raise ValueError("'after' must be a naive datetime")

    (
        minutes, hours, dom, months, dow, dom_star, dow_star
    ) = _compile(tuple(expr.split()))

    start = after.replace(
        second=0, microsecond=0, tzinfo=None
    ) + datetime.timedelta(minutes=1)

    # The stated input contract guarantees any next fire is before 3000.
    for year in range(start.year, 3000):
        for month in months:
            if year == start.year and month < start.month:
                continue

            same_month = year == start.year and month == start.month

            for day in _matching_days(
                year, month, dom, dow, dom_star, dow_star
            ):
                if same_month and day < start.day:
                    continue

                if same_month and day == start.day:
                    time = _time_at_or_after(
                        hours, minutes, start.hour, start.minute
                    )
                    if time is None:
                        continue
                    hour, minute = time
                else:
                    hour, minute = hours[0], minutes[0]

                return datetime.datetime(year, month, day, hour, minute)

    raise ValueError("Cron expression has no next fire time before year 3000")
